// "Value now" for the dashboard (see docs/prices.md). Deployed with --no-verify-jwt: the
// handler checks the caller's session with Supabase Auth itself and requires MFA (aal2)
// and the owner's user id, then reads and writes with that session so RLS applies.
// ../_shared/ledgr-jobs.js is generated by `pnpm functions:build` (packages/market).
import { handleValueNow } from '../_shared/ledgr-jobs.js';

Deno.serve((req: Request) => handleValueNow(req, Deno.env.toObject()));
